151	     * <p>A leading '+' and country code are kept when present; otherwise country code
152	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
153	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
154	     * carry 8 to 15 digits after the '+'.
155	     */
156	    private String toE164(String telephone) {
157	        if (telephone == null) {
158	            return null;
159	        }
160	        boolean hasCountryCode = telephone.trim().startsWith("+");
161	        String digits = telephone.replaceAll("\\D", "");
162	        String e164;
163	        if (hasCountryCode) {
164	            e164 = digits;
