package org.springframework.samples.petclinic.rest.controller.v1;

import org.springframework.stereotype.Component;

/**
 * Canonicalises a postal address into the single form used to compare and identify
 * owners' addresses, so that matching does not depend on incidental differences in
 * spacing or casing.
 *
 * <p>The canonical form trims surrounding whitespace, collapses internal runs of
 * whitespace to a single space and lower-cases the result. A {@code null} address
 * canonicalises to the empty string.
 */
@Component
public class AddressNormalizer {

    /**
     * Return the canonical form of {@code address} (see class documentation), or the
     * empty string when {@code address} is {@code null}.
     */
    public String normalize(String address) {
        if (address == null) {
            return "";
        }
        return address.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

